email = _email_from_token(token)
if not email:
    return _error_response(
        "no email claim", body)  # fail closed

# always overwrite what the LLM sent
args["userContext"] = {"userId": email}
return _pass_through(body)

permit(
  principal is AgentCore::OAuthUser,
  action == AgentCore::Action::"kb___Retrieve",
  resource == AgentCore::Gateway::"<ARN>"
) when {
  context.input.userContext.userId
    == principal.getTag("email")
};
